-- Mensaje 103 · Pedir permiso es condicionar el seguir a un sí; anunciar lo que vas a hacer y hacerlo no lo es (21-oct-2026).
-- Solo cambia si el resumen es el de antes. El chequeo final aborta si algo no quedó.
UPDATE public.reglas SET resumen = $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga. Pedir permiso es condicionar el seguir a que el cliente diga que sí: preguntárselo y esperar su respuesta, o ponerlo como condición («si no le molesta…»). Anunciar lo que vas a hacer y hacerlo en el mismo turno, sin condicionarlo —«quería preguntarle…» seguido de la pregunta—, no es pedir permiso: no le ofrece ninguna salida.$v$, updated_at = now() WHERE id = 'opening.pide_permiso' AND resumen = $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga.$v$;
UPDATE public.reglas SET resumen = $v$Aceptar el bloqueo pero no retomar. LA PRUEBA: después de aceptar, ¿el vendedor se queda callado esperando que el cliente le dé pie, o pide permiso para seguir (con la prueba de pedir permiso: condicionar el seguir a que el cliente diga que sí)? Si sigue con su tema o con una pregunta, sí retomó. Anunciar lo que va a hacer y hacerlo en el mismo turno («nada más quería preguntarle…» y la pregunta) es retomar, no pedir permiso.$v$, updated_at = now() WHERE id = 'blocks.air_sin_resume' AND resumen = $v$Aceptar el bloqueo pero no retomar. LA PRUEBA: después de aceptar, ¿el vendedor se queda callado esperando que el cliente le dé pie, o pide permiso para seguir (con la prueba de pedir permiso: una frase que le da al cliente la opción de decir que no a seguir)? Si sigue con su tema o con una pregunta, sí retomó.$v$;
DO $chk$ BEGIN
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.pide_permiso') IS DISTINCT FROM $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga. Pedir permiso es condicionar el seguir a que el cliente diga que sí: preguntárselo y esperar su respuesta, o ponerlo como condición («si no le molesta…»). Anunciar lo que vas a hacer y hacerlo en el mismo turno, sin condicionarlo —«quería preguntarle…» seguido de la pregunta—, no es pedir permiso: no le ofrece ninguna salida.$v$ THEN RAISE EXCEPTION 'la regla opening.pide_permiso no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.air_sin_resume') IS DISTINCT FROM $v$Aceptar el bloqueo pero no retomar. LA PRUEBA: después de aceptar, ¿el vendedor se queda callado esperando que el cliente le dé pie, o pide permiso para seguir (con la prueba de pedir permiso: condicionar el seguir a que el cliente diga que sí)? Si sigue con su tema o con una pregunta, sí retomó. Anunciar lo que va a hacer y hacerlo en el mismo turno («nada más quería preguntarle…» y la pregunta) es retomar, no pedir permiso.$v$ THEN RAISE EXCEPTION 'la regla blocks.air_sin_resume no quedó'; END IF;
END $chk$;
